# -*- coding: utf-8 -*-
"""Build the bilingual, dependency-free Gym Watch website. Python 3.9+."""
from pathlib import Path
from html import escape
import json
from hashlib import sha256
from functools import lru_cache
ROOT = Path(__file__).resolve().parents[1]
BASE = '/gymwatch-support/'
ORIGIN = 'https://winston-tao1.github.io'
CONFIG = json.loads((ROOT / 'site.json').read_text())
EMAIL = CONFIG.get('support_email', '')
ISSUES = 'https://github.com/Winston-Tao1/gymwatch-support/issues/new/choose'
DATE = '2026-10-08'

@lru_cache(maxsize=None)
def asset_url(name):
    version = sha256((ROOT / 'assets' / name).read_bytes()).hexdigest()[:10]
    return f'{BASE}assets/{name}?v={version}'

def img(name, alt='', cls='', eager=False):
    if name.endswith('.png') and (ROOT/'assets'/name.replace('.png','.webp')).exists():
        name=name.replace('.png','.webp')
    return f'<img src="{asset_url(name)}" alt="{escape(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async">'

def phone(name,alt,cls=''):
    capture = name.replace('iphone-', 'iphone-full-', 1)
    return f'<div class="phone {cls}"><div class="phone-capture">{img(capture,alt,eager=True)}</div></div>'

def watch(name,alt,kind='ultra',cls=''):
    frame = 'simulator-ultra4.png' if cls == 'front' else ('apple-ultra4.png' if kind == 'ultra' else 'apple-series12.png')
    components = ''
    if name == 'watch-cyber.png':
        components = f'<div class="face-cut-mode">{img("watch-cut-mode.png", "减脂模式圆形组件 / Cut mode complication", eager=True)}</div><div class="face-cyber-level">{img("watch-cyber-level1.png", "第一阶段赛博科技组件 / Level I Cyber Tech", eager=True)}</div>'
    return f'<div class="watch {kind} {cls}">{img(frame, "", "device-frame", eager=True)}<div class="watch-display">{img(name,alt,eager=True)}{components}</div></div>'

def page_path(zh, page=''):
    return BASE + ('zh/' if zh else '') + (page+'/' if page else '')

def contact(zh):
    if EMAIL:
        return f'<a class="button primary" href="mailto:{escape(EMAIL)}">{escape(EMAIL)} <span aria-hidden="true">↗</span></a>'
    return f'<a class="button primary" href="{ISSUES}">{"联系开发者（GitHub）" if zh else "Contact the developer on GitHub"} <span aria-hidden="true">↗</span></a>'

def shell(zh, page, title, desc, body):
    lang='zh-Hans' if zh else 'en'
    home=page_path(zh)
    other=page_path(not zh,page)
    nav=[('watch','Apple Watch'),('iphone','iPhone')]
    return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080c10"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="icon" href="{BASE}assets/icon.webp"><link rel="apple-touch-icon" href="{BASE}assets/icon.webp"><link rel="canonical" href="{ORIGIN}{page_path(zh,page)}"><link rel="alternate" hreflang="en" href="{ORIGIN}{page_path(False,page)}"><link rel="alternate" hreflang="zh-Hans" href="{ORIGIN}{page_path(True,page)}"><link rel="alternate" hreflang="x-default" href="{ORIGIN}{page_path(False,page)}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{ORIGIN}{page_path(zh,page)}"><meta property="og:image" content="{ORIGIN}{BASE}assets/icon.webp"><meta name="twitter:card" content="summary"><link rel="stylesheet" href="{asset_url('site.css')}"><script defer src="{BASE}assets/site.js"></script></head>
<body class="{'home-page' if not page else 'document-page'}"><a class="skip" href="#main">{'跳到正文' if zh else 'Skip to content'}</a>
<header class="site-header"><div class="nav-wrap"><a class="brand" href="{home}">{img('icon.png','',eager=True)}<span>{'健身人' if zh else 'Gym Watch'}</span></a><nav aria-label="{'主导航' if zh else 'Main navigation'}">{''.join(f'<a class="product-nav" href="{home}#{anchor}">{label}</a>' for anchor,label in nav)}<a href="{page_path(zh,'support')}">{'支持' if zh else 'Support'}</a><a href="{page_path(zh,'privacy')}">{'隐私' if zh else 'Privacy'}</a><a class="language" href="{other}" lang="{'en' if zh else 'zh-Hans'}" aria-label="{'Switch to English' if zh else '切换至简体中文'}">{'EN' if zh else '中文'}</a></nav></div></header>
<main id="main">{body}</main>
<footer><div class="footer-top"><a class="brand" href="{home}">{img('icon.png','')}<span>{'健身人' if zh else 'Gym Watch'}</span></a><p>{'把你的健身，戴在腕上。' if zh else 'A little motivation. A lot of personality.'}</p><div><a href="{page_path(zh,'support')}">{'支持与帮助' if zh else 'Support'}</a><a href="{page_path(zh,'privacy')}">{'隐私政策' if zh else 'Privacy Policy'}</a><a href="{other}">{'English' if zh else '简体中文'}</a></div></div><div class="footer-bottom"><span>© 2026 Gym Watch · 健身人</span><span>{'为 iPhone 与 Apple Watch 设计' if zh else 'Made for iPhone & Apple Watch'}</span></div><p class="trademark">{'Apple、iPhone、Apple Watch 和 App Store 是 Apple Inc. 的商标。本产品为独立开发，与 Apple Inc. 无关联或背书。' if zh else 'Apple, iPhone, Apple Watch, and App Store are trademarks of Apple Inc. Gym Watch is independently developed and is not affiliated with or endorsed by Apple Inc.'}</p></footer></body></html>'''

PERSONAS=[('muscleGainDisciplined','铁律队长','Iron Captain'),('muscleGainBalanced','举铁绅士','Iron Gentleman'),('muscleGainChill','小阿诺','Little Arnold'),('fatLossDisciplined','燃脂先锋','Burn Pioneer'),('fatLossBalanced','青卡侠','Calorie Hero'),('fatLossChill','轻盈玩家','Light Player'),('lifestyleDisciplined','节律大师','Rhythm Master'),('lifestyleBalanced','平衡大师','Balance Master'),('lifestyleChill','松弛大师','Chill Master')]

def home(zh):
    t=lambda c,e:c if zh else e
    goals='iphone-goals-zh.png' if zh else 'iphone-goals-en.png'
    data='iphone-data-zh.png' if zh else 'iphone-data-en.png'
    persona_cards=''.join(f'<div class="persona-item">{img("gym_mbti_"+key+".png",t("健身人格角色","Fitness persona character"))}</div>' for key,_,_ in PERSONAS)
    return f'''
<section class="hero section"><div class="hero-glow" aria-hidden="true"></div><p class="eyebrow"><span></span> FOR IPHONE & APPLE WATCH</p><h1>{t('你的健身<br><em>抬腕即见</em>','Fitness.<br><em>With personality.</em>')}</h1><p class="hero-sub">{t('健身人格 · 健身表盘 · 健身计划','Find your fitness persona. Make your watch face yours. Plan your next move.')}</p><a class="text-link" href="#discover">{t('认识健身人','Meet Gym Watch')} <span aria-hidden="true">↓</span></a>
<div class="hero-devices"><div class="hero-watch first">{watch('watch-training.png',t('训练统计与目标组件的表盘示例','Watch face with training statistics and goal complications'),'ultra')}<span class="device-caption">ULTRA 4 · NATURAL</span></div><div class="hero-phone">{phone(goals,t('iPhone 健身模式与训练计划界面','iPhone fitness modes and training plan'))}<span class="device-caption">IPHONE 18 PRO MAX · BLACK</span></div><div class="hero-watch last">{watch('watch-cyber.png',t('赛博科技表盘组件示例','Cyber-style watch complication'),'series')}<span class="device-caption">SERIES 12 · BLACK</span></div></div>
<p class="preview-note">{t('界面展示含示例数据 · 设备外观为展示示意','Screens include example data · Device frames are illustrative')}</p></section>
<div class="feature-ribbon"><span>{t('为你的腕上日常而生','Made for life on your wrist')}</span><span>{t('9 种健身人格','9 fitness personas')}</span><span>{t('4 种健身模式','4 fitness modes')}</span><span>{t('一周计划，随时掌握','Your week, at a glance')}</span></div>
<section class="section intro" id="discover"><p class="eyebrow">SMALL SCREEN. BIG PERSONALITY.</p><h2>{t('表盘，也可以<br>很有你的风格。','Your watch face.<br>Your kind of vibe.')}</h2><p class="lead">{t('训练有计划，进度看得见。把健身人格、今日目标和训练安排放在腕上，让每次抬腕，都多一点坚持的理由。','Give your watch face some personality. Add your daily goals, your next workout, and a fitness character that feels like you. A quick glance, a small nudge to keep going.')}</p></section>
<section class="section watch-feature" id="watch"><div class="section-copy"><p class="eyebrow">01 / ON YOUR WRIST</p><h2>{t('一眼，<br>看见你的节奏。','Less tapping.<br>More doing.')}</h2><p class="lead">{t('为 Apple Watch 表盘设计的组件，把你最在意的信息放在眼前。圆形进度、每周安排、训练趋势，按自己的习惯自由组合。','Make your Apple Watch face work for you. Pick the complications you want, from progress rings to weekly plans and training trends. Your favorites, one glance away.')}</p><div class="feature-list"><div><span>↗</span><p><strong>{t('目标与模式','Goals & modes')}</strong>{t('增肌、减脂、维持或摆烂，跟随今天的状态。','Build, Cut, Keep, or Chill. Going all in or taking it easy? There’s a mode for that.')}</p></div><div><span>▤</span><p><strong>{t('计划与趋势','Plans & trends')}</strong>{t('今天练什么，最近练得如何，抬腕就能了解。','Leg day or a day off? Check today’s plan and see how your training adds up.')}</p></div><div><span>✦</span><p><strong>{t('专属人格','Your fitness persona')}</strong>{t('让陪伴你的表盘，拥有一点自己的性格。','Meet the character that matches your approach to fitness. Give them a spot on your wrist.')}</p></div></div></div><div class="watch-showcase">{watch('watch-training.png',t('Ultra 模拟器正面展示训练统计组件','Ultra simulator showing training statistics'),'ultra','front')}<div class="orbit orbit-one" aria-hidden="true"></div><div class="orbit orbit-two" aria-hidden="true"></div></div></section>
<section class="section widget-section"><div class="center-heading"><p class="eyebrow">A QUICK LOOK GOES A LONG WAY</p><h2>{t('重要信息，刚刚好。','Small space.<br>Useful stuff.')}</h2></div><div class="widget-grid">{''.join(f'<article class="widget-tile">{img(file,t(c,e))}<h3>{t(c,e)}</h3><p>{t(dc,de)}</p></article>' for file,c,e,dc,de in [('health.png','健康概览','Health overview','最近训练、今日活动、最近睡眠，放在同一眼里。','Your latest workout, today’s activity, and recent sleep. Together at a glance.'),('training.png','训练统计','Training statistics','看看最近 30 天，你把更多时间安排给了哪里。','Chest day again? See which workouts you’ve planned most over the past 30 days.'),('weekly.png','一周运动量','Weekly activity','用一条轻盈的曲线，看见这一周的活动节奏。','Busy days. Easy days. See your week take shape in a simple activity curve.')])}</div><p class="preview-note">{t('图中为示例数据。表盘显示与刷新频率受 watchOS 和健康数据可用性影响。','Sample data shown. What appears and when it updates depend on watchOS and the health data available.')}</p></section>
<section class="section persona-section"><div class="center-heading"><p class="eyebrow">A PERSONAL TOUCH</p><h2>{t('认真练，也要<br><em>有点个性。</em>','Big goals.<br><em>Good company.</em>')}</h2><p class="lead">{t('九种健身人格，九种打开日常的方式。找到与你合拍的那个角色，让手机和手表都多一点乐趣。','The planner. The go-getter. The one who knows when to kick back. Explore nine fitness personas and find your kind of workout buddy for iPhone and Apple Watch.')}</p></div><div class="persona-grid">{persona_cards}</div></section>
<section class="section phone-feature" id="iphone"><div class="phone-pair">{phone(goals,t('训练计划界面','Training plan screen'),'phone-back')}{phone(data,t('健康与训练数据界面，示例数据','Health and training insights, example data'),'phone-front')}</div><div class="section-copy"><p class="eyebrow">02 / THE BIGGER PICTURE</p><h2>{t('腕上一眼，<br>手机上看全。','A quick glance.<br>The full picture.')}</h2><p class="lead">{t('在 iPhone 上安排一周训练，设置自己的目标，再把计划与活动数据放到一起看。小小的变化，也值得被看见。','Set your goals, map out your week, and see how your activity lines up with your plan. Your iPhone has room for the details, so you can spot the patterns behind your progress.')}</p><div class="numbered"><div><span>01</span><p><strong>{t('安排你的训练周','Make the week yours')}</strong>{t('胸、背、肩、腿、有氧与休息，都有自己的位置。','Chest, back, shoulders, legs, cardio, or a well-earned rest. Give each day a plan.')}</p></div><div><span>02</span><p><strong>{t('让数据有上下文','Give your numbers context')}</strong>{t('结合计划，比较训练消耗与全天活动消耗。','Compare average calories burned on chest days, leg days, and more. Switch between workout calories and all-day activity.')}</p></div><div><span>03</span><p><strong>{t('双端，一份节奏','Your phone and watch, in sync')}</strong>{t('手机与手表交换计划、偏好与可用的健康数据缓存。','Plans, preferences, and saved health summaries are shared between your paired iPhone and Apple Watch.')}</p></div></div></div></section>
<section class="section privacy-feature"><div class="privacy-mark" aria-hidden="true">⌁</div><p class="eyebrow">PERSONAL MEANS PERSONAL</p><h2>{t('你的健康数据，<br>留在你的设备里。','Personal data.<br>Stays personal.')}</h2><p class="lead">{t('按你的授权读取 Apple 健康，在设备上整理和呈现。不用创建账户，也没有广告追踪。配对的 iPhone 与 Apple Watch 通过 Apple 的设备连接机制交换数据。','You choose what Gym Watch can read from Apple Health. Your health data is processed on your devices and shared between your paired iPhone and Apple Watch using Apple’s device connectivity. No sign-up. No ad trackers.')}</p><a class="text-link" href="{page_path(zh,'privacy')}">{t('了解我们如何处理数据','Read our privacy policy')} <span aria-hidden="true">↗</span></a></section>
<section class="section final-cta">{img('icon.png','Gym Watch','cta-icon')}<h2>{t('下一次抬腕，<br>遇见更有趣的自己。','Give your fitness<br>a place on your wrist.')}</h2><p>{t('在 App Store 中搜索','Search the App Store for')}</p><div class="search-pill"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/></svg><span>Gym Watch / 健身人</span><button type="button" data-copy="Gym Watch" aria-label="{t('复制 App 名称','Copy app name')}">{t('复制','Copy')}</button></div><p class="availability">{t('应用正在准备上架，具体可用性以所在地区 App Store 为准。','Coming to the App Store. Availability may vary by region.')}</p><a class="text-link subtle" href="{page_path(zh,'support')}">{t('需要帮助？查看支持中心','Need a hand? Visit support')} ↗</a><p class="copy-status" role="status" aria-live="polite"></p></section>'''

FAQ_ZH=[('如何安装 Apple Watch App？','先在配对的 iPhone 上安装健身人，再打开 iPhone 的 Watch App，在“我的手表”的可用 App 列表中找到健身人并安装。请保持蓝牙及网络可用，并确认两台设备使用兼容的系统版本。'),('如何把组件添加到表盘？','长按 Apple Watch 表盘，点“编辑”，滑动到“复杂功能”，选择一个支持的圆形或矩形位置，再选择 Gym Watch / 健身人的组件。不同表盘可提供的位置和样式不同。'),('为什么健康数据是空白的？','请先分别打开 iPhone 和 Watch 上的 App，并允许读取所需的健康数据。在 iPhone 的“健康”App 中查看应用权限；同时检查 Watch 端的健康权限。设备必须已记录对应数据；没有样本或权限时会显示空白，而不会虚构数值。'),('“最近训练”的时间和心率表示什么？','它们来自最近一次可读取的体能训练记录。平均心率对应那次训练的时间范围，并不是实时心率。今日活动消耗属于今天，睡眠对应最近的睡眠记录，四项数据不属于同一时间段。'),('为什么表盘上的数字没有立刻刷新？','组件使用手表上的缓存，App 在健康读取或设置变化后请求刷新。实际刷新时间由 watchOS 调度，也会受后台权限、设备连接和健康样本写入时间影响。可先打开 Watch App 检查数据，再返回表盘；无法保证每秒或固定分钟间隔更新。'),('手机与手表不同步怎么办？','确认设备仍配对、蓝牙和网络可用，并分别打开两端 App。核对两端的健康权限。临时断连时，两端读取各自可用的数据；重新连接后会交换设置与缓存。如果持续不一致，请通过下方方式联系我们，并描述数据类型与观察时间。'),('部位消耗是在识别实际训练部位吗？','不是。部位消耗根据你设置的每日训练安排，关联体能训练消耗或全天活动消耗进行统计。Apple Watch 不会因此自动识别你实际练了哪个部位；全天活动消耗也不等同于那一部位的训练热量。请按实际情况及时更新计划。'),('如何切换语言、健身人格或模式？','在 iPhone 的设置页可选择跟随系统、简体中文或 English，并开启健身人格自定义。健身模式包含增肌、减脂、维持和摆烂；训练计划中的“休息”是另一项独立安排。'),('支持哪些设备？','当前版本面向 iPhone 与配对的 Apple Watch，最低部署目标为 iOS 17 和 watchOS 10。部分视觉效果随系统版本变化；最终兼容性以 App Store 页面为准。'),('如何停止读取健康数据？','你可以随时在系统的健康隐私设置中撤销健身人的读取权限。撤销权限会阻止后续读取，但不代表已经保存在 App 或配对设备中的缓存会立即消失。具体处理方式请阅读隐私政策。')]
FAQ_EN=[('How do I install Gym Watch on my Apple Watch?', 'Start by installing Gym Watch on your paired iPhone. Then open the Watch app on iPhone, go to My Watch, find Gym Watch under Available Apps, and tap Install. Keep Bluetooth on and make sure you have a network connection. Both devices need to be running a supported system version.'), ('How do I add Gym Watch to my watch face?', 'Touch and hold your Apple Watch face, tap Edit, then swipe to Complications. Pick a circular or rectangular slot and choose a Gym Watch complication. The slots and styles you can use depend on your watch face.'), ('Why am I seeing dashes instead of health data?', 'Open Gym Watch on both your iPhone and Apple Watch and allow it to read the health data you want to see. Check its permissions in the Health app on iPhone and on your watch. There also needs to be a recorded workout, activity, or sleep sample to display. If a reading is missing or access hasn’t been granted, you may see a dash.'), ('What does “recent workout” mean?', 'Workout duration and average heart rate come from your latest available workout record. The heart rate is the average for that session, not a live reading. Active calories are for today, while sleep comes from your latest sleep record. The four numbers cover different time periods.'), ('Why hasn’t my complication updated yet?', 'Complications show saved data from your watch. Gym Watch asks for an update after reading health data or changing settings, but watchOS decides when that update appears. Background access, your device connection, and when new health records are saved can all affect timing. Try opening Gym Watch on your watch to check the data, then return to your watch face. Updates aren’t guaranteed every second or on a fixed schedule.'), ('Why do my phone and watch show different numbers?', 'Make sure your devices are still paired, Bluetooth is on, and they have a connection. Open Gym Watch on both devices and check their health permissions. When disconnected, each device uses the data available locally. They exchange settings and saved summaries once reconnected. Still seeing a mismatch? Tell us which number differs and when you noticed it.'), ('Can Body Part Energy tell which muscles I trained?', 'No. It groups recorded workout calories or all-day active calories by the training category you planned for that day. For example, calories on a planned chest day are grouped under chest. Apple Watch isn’t identifying which muscles you used, and all-day active calories include activity beyond that workout. Keep your plan in line with what you actually did for more useful comparisons.'), ('How do I change my language, persona, or fitness mode?', 'Open Settings inside Gym Watch on iPhone. You can choose Follow System, Simplified Chinese, or English. Turn on Customize Fitness Persona to pick your own character. Fitness modes are Build, Cut, Keep, and Chill; a Rest day in your training plan is a separate choice.'), ('Will Gym Watch work on my devices?', 'The current version supports iPhone running iOS 17 or later and a paired Apple Watch running watchOS 10 or later. Some visual effects look different on older systems. Check the App Store listing for the final compatibility details.'), ('How do I turn off health data access?', 'You can turn off Gym Watch’s read permissions in your device’s Health privacy settings at any time. This stops future reads, but may leave data already saved in the app or on your paired device. The privacy policy explains how to remove that data.')]

def support(zh):
    t=lambda c,e:c if zh else e
    faq=FAQ_ZH if zh else FAQ_EN
    return f'''<section class="document-hero section"><p class="eyebrow">HERE TO HELP</p><h1>{t('每一步，<br><em>都有回应。</em>','Need a hand?<br><em>Start here.</em>')}</h1><p class="lead">{t('健身人支持中心。安装、权限、表盘与同步，从这里找到答案。','Getting set up, choosing complications, or sorting out a sync hiccup? You’re in the right place.')}</p></section><section class="section support-layout"><aside><p class="eyebrow">GET STARTED</p><a href="#setup">{t('开始使用','Getting started')}</a><a href="#questions">{t('常见问题','Common questions')}</a><a href="#contact">{t('联系开发者','Contact us')}</a></aside><div><section id="setup"><h2>{t('三个步骤，开始使用。','Up and running in three steps.')}</h2><div class="setup-grid"><article><span>01</span><h3>{t('安装双端 App','Install on both devices')}</h3><p>{t('在 iPhone 安装健身人，并通过 Watch App 安装到配对的手表。','Install Gym Watch on iPhone, then install the companion app on your paired watch.')}</p></article><article><span>02</span><h3>{t('允许健康读取','Choose your health data')}</h3><p>{t('分别打开双端 App，按你的需要允许读取健康数据。','Open Gym Watch on each device and choose which health data it can read.')}</p></article><article><span>03</span><h3>{t('打造自己的表盘','Make your watch face yours')}</h3><p>{t('设置健身模式与计划，再把喜欢的组件添加到表盘。','Pick a fitness mode, plan your week, and add your favorite complications to your watch face.')}</p></article></div></section><section id="questions"><h2>{t('你可能想问。','Good questions. Clear answers.')}</h2><div class="faq-list">{''.join(f'<details><summary>{escape(q)}<span aria-hidden="true">+</span></summary><p>{escape(a)}</p></details>' for q,a in faq)}</div></section><section id="contact" class="contact-card"><p class="eyebrow">LET’S FIGURE IT OUT</p><h2>{t('还有其他问题？','Still need a hand?')}</h2><p>{t('欢迎联系开发者，反馈问题或分享建议。','Something not working? Have an idea? Get in touch with the developer.')}</p>{contact(zh)}<a class="issue-link" href="{ISSUES}">{t('也可以提交 GitHub 问题反馈','You can also open a GitHub issue')} ↗</a><div class="report-template"><h3>{t('反馈时，附上这些会更有帮助','Helpful details to include')}</h3><ul><li>{t('App 版本、iPhone / Watch 型号及系统版本','App version, iPhone / Watch model, and system version')}</li><li>{t('问题出现在哪一页、操作步骤及预期结果','Affected screen, steps to reproduce, and expected behavior')}</li><li>{t('如果是同步问题，说明两台设备当时的连接状态','For sync issues, whether your phone and watch were connected')}</li></ul><p class="small">{t('请勿发送密码、Apple ID 验证码或完整健康记录。截图请先遮挡不想公开的个人信息。GitHub 反馈是公开的，隐私问题请使用邮箱。','Please leave out passwords, Apple ID verification codes, and full health records. Hide any personal details in screenshots before sending them. GitHub issues are public, so use email for anything private.')}</p></div></section></div></section>'''

POLICY_ZH=[
('适用范围与开发者','本政策适用于“健身人 / Gym Watch”的 iPhone App、Apple Watch App、表盘组件以及本支持网站。应用由本项目开发者 Winston-Tao1 维护。本文说明当前 1.0 版本的数据处理方式；Apple 和 GitHub 各自的服务还受其自身隐私政策约束。'),
('经你授权读取的健康数据','App 使用 Apple HealthKit，在获得相应授权后读取体能训练记录（包括时间、时长及可用的训练活动消耗）、心率、活动能量、步数和睡眠记录，用于健康概览、趋势与消耗统计。App 申请的是读取权限，不会向 Apple 健康写入记录。你可以只授权部分数据；相关功能可能因此显示空白或不完整信息。'),
('你在 App 中设置的信息','健身模式、健身人格选择、训练计划、热量与步数目标、目标体重、语言及外观偏好保存在设备本地。目标体重是你填写的目标，不是 App 从健康库自动读取的实际体重。人格选择和计划关联统计在设备上完成；App 不会为了这些功能把健康信息发送给云端 AI 服务。'),
('处理、存储与配对设备同步','iPhone 与 Apple Watch 分别读取本机可用的健康记录，生成统计和显示缓存。App 使用本地存储及 App Group 在 App 与组件之间共享必要数据，并通过 Apple WatchConnectivity 在配对的手机和手表之间交换设置、计划及健康数据摘要。组件读取缓存；更新时机由系统调度。当前版本不要求创建账户，也没有用于接收用户健康记录的开发者服务器。设备系统备份的行为由 Apple 服务和你的备份设置决定。'),
('统计的含义','部位消耗依据你设置的训练日安排，关联体能训练或全天活动消耗，不是对实际肌肉训练部位的自动识别。最近训练、今日消耗与最近睡眠采用不同的时间范围。网站及组件选择界面可以使用明确标注的示例数据，示例并非你的实际健康记录。App 提供健身信息展示，不用于诊断或治疗。'),
('广告、追踪与第三方分析','当前 App 不集成广告、跨 App 追踪或第三方使用行为分析 SDK。我们不将通过 HealthKit 获得的数据出售、用于广告投放或交给广告商。当前网站不安装广告或访问分析脚本，不使用营销 Cookie，也不嵌入第三方视频播放器。'),
('网站托管与访问日志','本网站由 GitHub Pages 托管。根据 GitHub 的说明，访问 GitHub Pages 时，GitHub 会为安全目的记录并保存访客 IP 地址；网络服务还可能处理提供页面所需的技术请求信息。这与 App 的本地健康数据处理是不同的。有关 GitHub 的处理方式，请参阅其隐私声明。本站的图片、样式和脚本随网站一同提供。'),
('主动联系支持','如果你通过支持邮箱联系我们，我们会收到你主动发送的邮箱地址、消息及附件，用于回复与排查问题；邮件还由相应邮件服务商处理。如果通过 GitHub Issues 提交问题，内容和 GitHub 用户身份会公开，并由 GitHub 处理。请只提供解决问题必需的信息，不要公开完整健康记录或账户凭据。支持来信在处理请求所需的期间内保留；你可以联系开发者申请删除我们持有的支持通信，适用法律要求保留的情况除外。'),
('你的选择与删除','你可以在 Apple 的健康隐私设置中撤销读取权限，或在 App 中修改自己的目标、计划和偏好。撤销健康权限不会自动清除已生成的本地缓存；若要移除 App 数据，需要在 iPhone 和 Apple Watch 上分别删除 App（不是仅卸载并保留数据），并按需管理系统备份。配对设备、组件和系统备份可能有各自的数据副本，因此不承诺撤权或单端删除后立即删除所有副本。App 不会删除 Apple 健康中原有的记录。关于支持通信的访问或删除，可通过下方邮箱联系。'),
('儿童与数据安全','本产品不面向 13 岁以下儿童提供定向服务，也不主动要求儿童提交个人信息。如果你认为儿童通过支持渠道发送了个人信息，请联系我们处理。我们尽量减少需要处理的信息，并依赖 iOS、watchOS 和 Apple 提供的权限与设备存储保护。没有任何设备或传输方式能够保证绝对安全。'),
('政策更新与联系','功能或数据处理方式发生变化时，我们会更新本页面及生效日期。对本政策、数据访问或支持通信删除有疑问，请联系开发者。')]
POLICY_EN=[
('About this policy', 'This policy applies to the Gym Watch / 健身人 apps for iPhone and Apple Watch, their watch complications, and this support website. Gym Watch is maintained by the project developer Winston-Tao1. This page describes how version 1.0 handles data. Apple and GitHub services are also subject to their own privacy policies.'),
('Health data you choose to allow', 'With your permission, Gym Watch uses Apple HealthKit to read workout records, heart rate, active energy, steps, and sleep records. Workout records include the time, duration, and active calories where available. This data powers health summaries, trends, and calorie statistics. The app only reads health data; it does not write records to Apple Health. You can allow some data types and decline others. Features that depend on data you haven’t allowed may show missing or incomplete information.'),
('Settings and plans you create', 'Your fitness mode, persona, training plans, calorie and step goals, target weight, language, and appearance preferences are stored on your device. Target weight is a goal you enter, not your measured weight read from Apple Health. Persona selection and statistics linked to your plan are processed on your device. Gym Watch does not send health information to a cloud AI service for these features.'),
('Storage and syncing between your devices', 'Your iPhone and Apple Watch each read the health records available on that device and save summaries for display. Gym Watch uses local storage and an App Group to share the data needed by its complications. It uses Apple’s WatchConnectivity framework to exchange settings, plans, and health summaries between your paired phone and watch. Complications display saved summaries, and the system controls when they update. Version 1.0 does not require an account, and the developer does not run a server that receives your health records. Device backups are handled by Apple’s services according to your backup settings.'),
('How to read the statistics', 'Body Part Energy groups workout calories or all-day active calories according to the training category you planned for each day. It does not detect which muscles you actually trained. Recent workout, today’s activity, and latest sleep figures cover different time periods. Website images and previews in the complication gallery may show labeled sample data, rather than your own health records. Gym Watch displays fitness information and is not intended to diagnose or treat medical conditions.'),
('Ads, tracking, and analytics', 'The current app has no ads, cross-app tracking, or third-party usage analytics SDKs. We do not sell data obtained through HealthKit, use it for advertising, or share it with advertisers. This website has no advertising or analytics scripts, marketing cookies, or embedded third-party video players.'),
('Website hosting and access logs', 'This website is hosted on GitHub Pages. GitHub states that it logs and stores visitors’ IP addresses for security purposes. Network services may also process the technical request information needed to deliver the website. This is separate from the health data Gym Watch processes on your devices. See GitHub’s privacy statement for details. The website serves its own images, styles, and scripts.'),
('If you contact support', 'When you email support, we receive the email address, message, and attachments you send so we can reply and investigate the issue. The email providers involved also process these messages. GitHub issues are public: your report and GitHub identity are visible and handled by GitHub. Please share only what we need to help, and leave out full health records and account credentials. We keep support messages for as long as needed to handle your request. You can ask us to delete messages we hold, unless we are required by law to retain them.'),
('Your controls and deleting data', 'You can turn off read access in Apple’s Health privacy settings and change your goals, plans, and preferences in Gym Watch. Turning off access does not automatically erase summaries already saved in the app. To remove app data, delete Gym Watch from both your iPhone and Apple Watch, rather than offloading it and keeping its data. Manage your system backups separately as needed. Paired devices, complications, and backups may hold their own copies, so turning off access or deleting the app on one device does not guarantee that every copy is removed immediately. Gym Watch does not delete your original Apple Health records. To request access to or deletion of support messages, contact us below.'),
('Children and data security', 'Gym Watch is not directed at children under 13, and we do not actively ask children to submit personal information. If you believe a child has sent personal information through a support channel, please contact us. We aim to handle as little information as needed and rely on the permissions and device storage protections provided by iOS, watchOS, and Apple. No device or method of sending data can guarantee absolute security.'),
('Updates and questions', 'If features or data practices change, we will update this page and its effective date. Contact the developer if you have questions about this policy, access to your data, or deleting support messages.'),
]

def privacy(zh):
    t=lambda c,e:c if zh else e
    sections=POLICY_ZH if zh else POLICY_EN
    return f'''<section class="document-hero section"><p class="eyebrow">YOUR DATA. YOUR CHOICE.</p><h1>{t('隐私，<br><em>认真对待。</em>','Your data.<br><em>Your call.</em>')}</h1><p class="lead">{t('了解健身人读取什么、保存在哪里，以及你如何控制自己的数据。','Here’s what Gym Watch reads, where your data stays, and the choices you have.')}</p><p class="policy-date">{t('生效日期','Effective date')}: {DATE} · {t('适用版本','App version')} 1.0</p></section><section class="section policy-layout"><aside><p class="eyebrow">{t('本页目录','ON THIS PAGE')}</p>{''.join(f'<a href="#policy-{i}">{escape(title)}</a>' for i,(title,_) in enumerate(sections,1))}</aside><article class="policy"><div class="policy-summary"><span>↗</span><p>{t('健康数据在你的设备上读取和处理。无需注册账户，不向开发者服务器上传健康记录。支持来信与网站托管日志另行说明如下。','Gym Watch reads and processes health data on your devices. You don’t need an account, and your health records aren’t uploaded to a server run by the developer. Support messages and website access logs are covered separately below.')}</p></div>{''.join(f'<section id="policy-{i}"><h2><span>{i:02d}</span> {escape(title)}</h2><p>{escape(copy)}</p></section>' for i,(title,copy) in enumerate(sections,1))}<div class="policy-contact">{contact(zh)}<p><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy Statement ↗</a></p><p><a href="https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages#data-collection">GitHub Pages: Data collection ↗</a></p></div></article></section>'''

for zh in [False,True]:
    for route,func in [('',home),('support',support),('privacy',privacy)]:
        title=({'':'健身人 · 专属健身表盘','support':'支持与帮助 · 健身人','privacy':'隐私政策 · 健身人'} if zh else {'':'Gym Watch · Fitness with character','support':'Support · Gym Watch','privacy':'Privacy Policy · Gym Watch'})[route]
        desc=('健身人格、健身表盘与健身计划。为 iPhone 和 Apple Watch 设计的健身伙伴。' if zh else 'Give your fitness some personality. Customize your Apple Watch face, plan your workouts, and explore your progress with Gym Watch for iPhone and Apple Watch.')
        out=ROOT/('zh' if zh else '')/route/'index.html'
        out.parent.mkdir(parents=True,exist_ok=True)
        out.write_text(shell(zh,route,title,desc,func(zh)),encoding='utf-8')
paths=[page_path(zh,p) for zh in [False,True] for p in ['', 'support','privacy']]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{p}</loc><lastmod>{DATE}</lastmod></url>' for p in paths)+'</urlset>')
(ROOT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}{BASE}sitemap.xml\n')
(ROOT/'404.html').write_text(shell(False,'','Page not found · Gym Watch','Return to Gym Watch.',f'<section class="section document-hero"><p class="eyebrow">404</p><h1>A little off track.</h1><p class="lead">This page could not be found. / 没有找到这个页面。</p><a class="button primary" href="{BASE}">Back to Gym Watch ↗</a></section>'))
print('Built 6 bilingual pages, 404, sitemap and robots.')
